#include <WiFi.h>
#include <WebServer.h>

// Название и пароль Wi-Fi сети
const char* ssid = "ESP32-Control";
const char* password = "12345678";

// Встроенный светодиод
const int LED_PIN = 8;

// У некоторых плат светодиод включается уровнем LOW
const int LED_ON = LOW;
const int LED_OFF = HIGH;

WebServer server(80);

bool ledState = false;

String makePage() {
  String stateText = ledState ? "ВЫКЛЮЧИТЬ" : "ВКЛЮЧИТЬ";
  String color = ledState ? "#e74c3c" : "#16a34a";

  String page = R"rawliteral(
<!DOCTYPE html>
<html lang="ru">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>ESP32 Control</title>
  <style>
    body {
      background: #101014;
      color: white;
      font-family: Arial, sans-serif;
      text-align: center;
      padding: 50px 15px;
    }
    .card {
      max-width: 340px;
      margin: auto;
      padding: 25px;
      background: #202027;
      border-radius: 20px;
    }
    button {
      width: 100%;
      padding: 18px;
      border: none;
      border-radius: 12px;
      color: white;
      font-size: 18px;
      font-weight: bold;
      cursor: pointer;
    }
    .status {
      margin: 25px 0;
      font-size: 20px;
    }
  </style>
</head>
<body>
  <div class="card">
    <h1>ESP32 Control</h1>
    <div class="status">Светодиод: <b>%STATE%</b></div>
    <form action="/toggle" method="POST">
      <button style="background:%COLOR%" type="submit">%BUTTON%</button>
    </form>
  </div>
</body>
</html>
)rawliteral";

  page.replace("%STATE%", ledState ? "ВКЛЮЧЁН" : "ВЫКЛЮЧЕН");
  page.replace("%COLOR%", color);
  page.replace("%BUTTON%", stateText);

  return page;
}

void showPage() {
  server.send(200, "text/html; charset=utf-8", makePage());
}

void toggleLED() {
  ledState = !ledState;

  digitalWrite(LED_PIN, ledState ? LED_ON : LED_OFF);

  server.sendHeader("Location", "/");
  server.send(303);
}

void setup() {
  Serial.begin(115200);

  pinMode(LED_PIN, OUTPUT);
  digitalWrite(LED_PIN, LED_OFF);

  WiFi.mode(WIFI_AP);
  WiFi.softAP(ssid, password);

  Serial.println();
  Serial.println("Wi-Fi сеть создана!");
  Serial.print("Название: ");
  Serial.println(ssid);
  Serial.print("Адрес сайта: ");
  Serial.println(WiFi.softAPIP());

  server.on("/", HTTP_GET, showPage);
  server.on("/toggle", HTTP_POST, toggleLED);

  server.begin();
}

void loop() {
  server.handleClient();
}
